/// Where a session started at `now` is recorded for the user whose home
/// directory is `home`.
fn recording_path(home: &Path, now: DateTime<Utc>) -> PathBuf {
    home.join(".agent_runtime_sessions")
        .join(format!("{}.jsonl", now.format("%Y-%m-%dT%H-%M-%SZ")))
}

/// Append recorded lines to the session file until every sink handle drops.
///
/// Flushes after every line so a session killed mid-run keeps its data.
async fn run_writer(
    path: PathBuf,
    mut lines: mpsc::UnboundedReceiver<String>,
) -> std::io::Result<()> {
    if let Some(parent) = path.parent() {
        tokio::fs::create_dir_all(parent).await?;
    }
    let mut file = tokio::fs::File::create(&path).await?;
    while let Some(line) = lines.recv().await {
        file.write_all(line.as_bytes()).await?;
        file.write_all(b"\n").await?;
        file.flush().await?;
    }
    file.flush().await
}

