    let update = line(
        "to_server",
        json!({"type": "acp", "jsonrpc": "2.0", "method": "session/update", "params": {"sessionId": "sess-1", "update": {}}}),
    );
    assert_eq!(router.route(update.clone()), vec![session("sess-1", &update)]);
}

#[test]
