#!/usr/bin/env python3
"""Split per-process agent_session_recorder JSONL files into per-session files.

Mirrors the routing in crates/agent_session/examples/agent_session_recorder.rs:

- lines naming `params.sessionId` go to that session's file;
- responses are attributed via the JSON-RPC id of the request they answer
  (ids are scoped by the direction of the request);
- a request naming no session is held until its response shows whether it
  minted a session (`session/new`);
- connection-level lines (acp_ready, the initialize pair) are copied into
  every session file so each recording stands alone.

Usage: python3 split_recording.py <recording.jsonl> [...]

Output files land next to each source as <session-id>.jsonl. Files are
OVERWRITTEN on the first touch of a run (re-running is idempotent for the
same sources), so re-run this only on the old per-process files — not after
the new per-session recorder has appended to a session file this would clobber.
The source files are left untouched.
"""

import json
import sys
from pathlib import Path


def opposite(direction):
    return "to_runtime" if direction == "to_server" else "to_server"


def sanitize(session_id):
    return "".join(
        c if c.isascii() and (c.isalnum() or c in "-_.") else "_" for c in session_id
    )


def split(source: Path):
    """Return ({session_id: [lines]}, [unattributable lines])."""
    shared = []  # connection-level lines, copied into every session file
    sessions = {}

    # (issuer direction, id json) -> ("session", sid) | ("unattributed", line)
    pending = {}

    def to_session(sid, line):
        if sid not in sessions:
            sessions[sid] = list(shared)
        sessions[sid].append(line)

    def to_shared(line):
        shared.append(line)
        for lines in sessions.values():
            lines.append(line)

    for raw in source.read_text().splitlines():
        if not raw.strip():
            continue
        value = json.loads(raw)
        direction = value.get("direction")
        content = value.get("content") or {}
        method = content.get("method")
        rpc_id = json.dumps(content["id"]) if content.get("id") is not None else None
        params = content.get("params")
        sid = params.get("sessionId") if isinstance(params, dict) else None

        if method is not None and rpc_id is not None:  # request
            if sid is not None:
                pending[(direction, rpc_id)] = ("session", sid)
                to_session(sid, raw)
            else:
                pending[(direction, rpc_id)] = ("unattributed", raw)
        elif method is not None:  # notification
            to_session(sid, raw) if sid is not None else to_shared(raw)
        elif rpc_id is not None:  # response
            kind, val = pending.pop((opposite(direction), rpc_id), (None, None))
            if kind == "session":
                to_session(val, raw)
            elif kind == "unattributed":
                result = content.get("result")
                minted = result.get("sessionId") if isinstance(result, dict) else None
                if minted is not None:
                    to_session(minted, val)
                    to_session(minted, raw)
                else:
                    to_shared(val)
                    to_shared(raw)
            else:
                to_shared(raw)
        else:  # not JSON-RPC, e.g. the acp_ready event
            to_shared(raw)

    # Requests that never got a response (connection died mid-request).
    for key in sorted(pending):
        kind, val = pending[key]
        if kind == "unattributed":
            to_shared(val)

    return sessions


def main():
    sources = [Path(arg).expanduser() for arg in sys.argv[1:]]
    if not sources:
        sys.exit(__doc__)

    touched = set()
    for source in sources:
        sessions = split(source)
        if not sessions:
            print(f"{source}: no sessions found")
            continue
        for sid, lines in sessions.items():
            target = source.parent / f"{sanitize(sid)}.jsonl"
            if target.resolve() == source.resolve():
                sys.exit(f"refusing to overwrite source {source}")
            mode = "a" if target in touched else "w"
            with open(target, mode) as f:
                f.write("\n".join(lines) + "\n")
            touched.add(target)
            print(f"{source.name}: {len(lines):4} lines -> {target.name}")


if __name__ == "__main__":
    main()

